function checkPasswordStrength(password){const errors=[];return/.{6,}/.test(password)||errors.push("Setidaknya 6 karakter"),errors}document.getElementById("password").addEventListener("input",e=>{const errors=checkPasswordStrength(e.target.value),passwordFeedback=document.getElementById("passwordFeedback");errors.length?(passwordFeedback.innerText=errors.join(", "),passwordFeedback.setAttribute("style","display:block;")):passwordFeedback.innerText=""}),document.getElementById("auth_confirm_password").addEventListener("input",e=>{const password=document.getElementById("password").value,confirmPasswordFeedback=document.getElementById("confirmPasswordFeedback");e.target.value.length>5&&e.target.value!==password?(confirmPasswordFeedback.innerText="Konfirmasi password tidak sesuai",confirmPasswordFeedback.setAttribute("style","display:block;")):confirmPasswordFeedback.innerText=""});